import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"A menu","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/menu.md","filePath":"patterns/menu.md"}'),i={name:"patterns/menu.md"};function r(s,e,d,h,l,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="a-menu" tabindex="-1">A menu <a class="header-anchor" href="#a-menu" aria-label="Permalink to &quot;A menu&quot;">​</a></h1><p>A menu is a list of actions that opens from a trigger and closes when one is chosen. In kata a menu is described once, as data (<code>MenuModel[]</code>), and drawn wherever it opens.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use a menu for actions that do not need to be seen all the time: the actions of an item, a group of commands in a bar, the menu of the application. Two or three actions that are used often are buttons instead; a choice of one value is a <a href="./../components/select">Select</a> or a <a href="./../components/segmented">Segmented</a> control.</p><h2 id="parts" tabindex="-1">Parts <a class="header-anchor" href="#parts" aria-label="Permalink to &quot;Parts&quot;">​</a></h2><ul><li>The model, <code>MenuModel[]</code>: items with an <code>id</code>, a <code>label</code> and an optional <code>icon</code>, <code>kbd</code>, <code>checked</code>, <code>danger</code> or submenu <code>items</code>, with <code>{ divider: true }</code> and <code>{ heading }</code> between them (<a href="./../workbench/menu-list">MenuList</a> describes it).</li><li>A button that opens it: a <a href="./../components/dropdown">Dropdown</a> with <code>menu</code> and a <a href="./../workbench/menu-list">MenuList</a> inside.</li><li>The actions of an item: a <a href="./../components/kebab">Kebab</a> at the end of the item, with <code>items</code>.</li><li>The menu of the application: <code>menu</code> on the <a href="./../components/topbar">Topbar</a>, or an <a href="./../workbench/app-menu">AppMenu</a> behind one button. On a phone the same model goes in a <a href="./../workbench/menu-sheet">MenuSheet</a>.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>Order the items by use, group them with dividers, and put a destructive item last, with <code>danger</code> and an ellipsis when it asks before it acts.</li><li>A key hint shows the shortcut that does the same thing; the shortcut itself is attached by the <a href="./../workbench/shell">Shell</a>.</li><li>A submenu opens next to its item; below 48rem it takes the place of the list. Keep menus one level deep where you can.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/pattern-menu/" title="A menu" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/pattern-menu/" target="_blank" rel="noopener">A menu</a></figcaption></figure>',10)])])}const p=a(i,[["render",r]]);export{m as __pageData,p as default};
